code.source:
#include <iostream>
#include <thread>
using namespace std;

int main() {
    int result = 0;
    thread t([&result]() {
        for (int i = 1; i <= 100; ++i) {
            result += i;
        }
    });
    t.join();
    cout << result << endl;
    return 0;
}

#include <iostream>
#include <mutex>
#include <thread>
using namespace std;

int main() {
    int counter = 0;
    mutex m;
    auto work = [&]() {
        for (int i = 0; i < 1000; ++i) {
            lock_guard<mutex> lock(m);
            ++counter;
        }
    };
    thread a(work);
    thread b(work);
    a.join();
    b.join();
    cout << counter << endl;
    return 0;
}

